create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null check(type in('quota_warning','renewal_reminder','referral_reward','leaderboard_win','system')),title text not null,body text not null,is_read boolean not null default false,created_at timestamptz not null default now());create index if not exists idx_not_u on public.notifications(user_id);create index if not exists idx_not_ur on public.notifications(user_id,is_read) where is_read=false;
